(() => {
'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Smartphones','Computadores','Áudio','Gaming','Wearables','Acessórios'];
const draftKey='ts-admin-draft-v1';let content,base,assets=[],dirty=false,draftSaved=true,editing=null,editingIndex=-1,editingType='',busy=false;
const money=n=>n===null?'Preço sob consulta':new Intl.NumberFormat('pt-MZ',{style:'currency',currency:'MZN'}).format(n);
const copy=o=>JSON.parse(JSON.stringify(o));
const stable=v=>JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b))):x);
const img=path=>{const a=assets.find(a=>a.path===path);return a?'data:image/webp;base64,'+a.data:path;};
function notice(text,isError=false){$('#notice').hidden=!text;$('#notice').textContent=text;$('#notice').classList.toggle('error',isError);}
async function api(body){const response=await fetch('/api/admin',body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{cache:'no-store'});const result=await response.json().catch(()=>({error:'O servidor não respondeu. Tente novamente.'}));if(!response.ok){const e=new Error(result.error);e.status=response.status;throw e;}return result;}
function changed(){dirty=true;draftSaved=false;$('#draft-state').textContent='Alterações por publicar';$('#publish').disabled=false;}
function saveDraft(show=true){try{localStorage.setItem(draftKey,JSON.stringify({version:1,base,content,assets,savedAt:new Date().toISOString()}));draftSaved=true;if(show)notice('Rascunho guardado neste navegador. Ainda não está publicado.');$('#draft-state').textContent='Rascunho guardado · por publicar';return true;}catch{notice('Não há espaço para guardar o rascunho neste navegador. Mantenha esta página aberta e publique, ou reduza as imagens.',true);return false;}}
function renderProducts(){const filter=$('#filter').value.toLocaleLowerCase();const visible=content.products.map((p,i)=>({p,i})).filter(({p})=>(p.name+' '+p.id).toLocaleLowerCase().includes(filter));$('#count-total').textContent=content.products.length;$('#count-active').textContent=content.products.filter(p=>p.active).length;$('#count-images').textContent=content.products.filter(p=>p.image).length;$('#count-results').textContent=visible.length+' produtos';$('#product-list').innerHTML=visible.length?visible.map(({p,i})=>`<article class="admin-product-card"><div class="product-thumb">${p.image?`<img src="${esc(img(p.image))}" alt="${esc(p.name)}">`:'<span class="placeholder">▧<br>Sem fotografia</span>'}<span class="status-badge ${p.active?'':'off'}">${p.active?'Visível':'Oculto'}</span></div><div class="card-body"><span class="category">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p>${money(p.price)}</p><button data-edit-product="${i}">Editar produto →</button></div></article>`).join(''):'<div class="empty"><h2>Nenhum produto encontrado.</h2><p>Experimente outra pesquisa ou adicione um novo produto.</p></div>';}
function mediaMarkup(paths,kind){return paths.filter(Boolean).map((path,i)=>`<div class="media-item"><img src="${esc(img(path))}" alt="Imagem ${i+1}"><button type="button" data-remove-image="${i}" data-kind="${kind}">Remover ${i===0&&kind==='product'?'principal':'imagem'}</button></div>`).join('');}
function renderBanners(){$('#banner-list').innerHTML=content.banners.length?content.banners.map((b,i)=>`<article class="banner-card">${b.image?`<img src="${esc(img(b.image))}" alt="">`:''}<div><span class="eyebrow">${b.active?'VISÍVEL':'OCULTO'}</span><h3>${esc(b.title)}</h3><p>${esc(b.description)}</p><button data-edit-banner="${i}">Editar destaque →</button></div></article>`).join(''):'<p class="hint">Ainda não há destaques adicionais. Adicione uma novidade, campanha ou categoria em destaque.</p>';$('#hero-image').innerHTML=mediaMarkup([content.hero.image],'hero');}
function fillForms(){for(const [k,v]of Object.entries(content.hero)){const el=$('#hero-form').elements[k];if(el)el.value=v;}$('#pages-form').elements.announcement.value=content.announcement;$('#pages-form').elements.about.value=content.about;$('#pages-form').elements.sampleCatalogue.checked=content.sampleCatalogue;}
function render(){renderProducts();renderBanners();fillForms();}
function syncForms(){if(!$('#hero-form').reportValidity()||!$('#pages-form').reportValidity())return false;for(const k of ['eyebrow','title','description','button'])content.hero[k]=$('#hero-form').elements[k].value.trim();content.announcement=$('#pages-form').elements.announcement.value.trim();content.about=$('#pages-form').elements.about.value.trim();content.sampleCatalogue=$('#pages-form').elements.sampleCatalogue.checked;return true;}
async function load(){const data=await api();content=data.content;base=data.head;assets=[];dirty=false;$('#login-view').hidden=true;$('#admin-view').hidden=false;$('#publish').disabled=true;render();try{$('#saved-draft').hidden=!localStorage.getItem(draftKey);}catch{}$('#draft-state').textContent='Conteúdo publicado';}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;$('#login-message').textContent='A entrar…';try{await api({action:'login',password:e.target.password.value});e.target.password.value='';await load();}catch(err){$('#login-message').textContent=err.message;}finally{b.disabled=false;}});
$('#logout').onclick=async()=>{if(dirty&&!saveDraft())return;try{await api({action:'logout'});location.reload();}catch(e){notice(e.message,true);}};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{for(const name of ['products','banners','pages'])$('#'+name+'-view').hidden=name!==b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('selected',el===b));});
$('#filter').oninput=renderProducts;
function openEditor(type,index){editingType=type;editingIndex=index;editing=copy(index<0?(type==='product'?{id:'produto-'+crypto.randomUUID().slice(0,8),name:'',category:categories[0],description:'',price:null,image:'',images:[],active:true}:{title:'',description:'',image:'',button:'Ver produtos',href:'#produtos',active:true}):(type==='product'?content.products[index]:content.banners[index]));$('#editor-kind').textContent=type==='product'?'CATÁLOGO':'DESTAQUE';$('#editor-title').textContent=(index<0?'Novo ':'Editar ')+(type==='product'?'produto':'destaque');$('#editor-message').textContent='';
 $('#editor-fields').innerHTML=type==='product'?`<div class="form-grid"><label class="wide">Nome do produto<input name="name" required maxlength="160" value="${esc(editing.name)}"></label><label>Categoria<select name="category">${categories.map(c=>`<option ${c===editing.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Preço (MZN)<input name="price" type="number" min="0" max="1000000000" step="0.01" placeholder="Sob consulta" value="${editing.price??''}"></label><label class="wide">Descrição<textarea name="description" rows="5" maxlength="8000">${esc(editing.description)}</textarea></label></div><p class="hint">Deixe o preço em branco para mostrar “Preço sob consulta”. Referência: ${esc(editing.id)}</p><h3>Fotografias</h3><div id="editor-media" class="media-strip"></div><label class="upload">Adicionar fotografias<input id="product-upload" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><p class="hint">A primeira fotografia será a imagem principal. Até 9 fotografias por produto; são optimizadas automaticamente.</p><label class="check"><input name="active" type="checkbox" ${editing.active?'checked':''}> Visível na loja</label>`:`<label>Título<input name="title" maxlength="160" required value="${esc(editing.title)}"></label><label>Descrição<textarea name="description" maxlength="600" rows="3">${esc(editing.description)}</textarea></label><div class="form-grid"><label>Texto do botão<input name="button" maxlength="60" required value="${esc(editing.button)}"></label><label>Destino<select name="href">${[['#produtos','Catálogo'],['#categorias','Categorias'],['sobre.html','Sobre nós'],['politicas.html','Políticas e FAQs']].map(([v,t])=>`<option value="${v}" ${editing.href===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="editor-media" class="media-strip"></div><label class="upload">Imagem do destaque<input id="banner-upload" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="check"><input name="active" type="checkbox" ${editing.active?'checked':''}> Visível na loja</label>`;
 $('#editor-media').innerHTML=mediaMarkup(type==='product'?[editing.image,...editing.images]:[editing.image],type);const upload=$('#'+type+'-upload');if(upload)upload.onchange=async e=>{try{const current=type==='product'?[editing.image,...editing.images].filter(Boolean):[];if(current.length+e.target.files.length>9)throw new Error('Máximo de 9 fotografias por produto.');$('#editor-message').textContent='A optimizar imagens…';for(const file of e.target.files){const path=await uploadImage(file);if(type==='product')current.push(path);else editing.image=path;}if(type==='product'){editing.image=current[0]||'';editing.images=current.slice(1);}$('#editor-media').innerHTML=mediaMarkup(type==='product'?current:[editing.image],type);$('#editor-message').textContent='Imagens prontas. Aplique ao rascunho para guardar.';}catch(err){$('#editor-message').textContent=err.message;}finally{e.target.value='';}};$('#editor').showModal();}
$('#new-product').onclick=()=>{if(content.products.length>=200)return notice('Máximo de 200 produtos.',true);openEditor('product',-1);};$('#new-banner').onclick=()=>{if(content.banners.length>=8)return notice('Máximo de 8 destaques.',true);openEditor('banner',-1);};
document.addEventListener('click',e=>{const p=e.target.closest('[data-edit-product]'),b=e.target.closest('[data-edit-banner]'),remove=e.target.closest('[data-remove-image]');if(p)openEditor('product',Number(p.dataset.editProduct));if(b)openEditor('banner',Number(b.dataset.editBanner));if(remove){if(remove.dataset.kind==='hero'){content.hero.image='';changed();renderBanners();}else{const paths=editingType==='product'?[editing.image,...editing.images].filter(Boolean):[editing.image];paths.splice(Number(remove.dataset.removeImage),1);editing.image=paths[0]||'';if(editingType==='product')editing.images=paths.slice(1);$('#editor-media').innerHTML=mediaMarkup(paths,editingType);}}});
$('#editor-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements;if(editingType==='product'){editing.name=f.name.value.trim();editing.category=f.category.value;editing.description=f.description.value.trim();editing.price=f.price.value===''?null:Number(f.price.value);editing.active=f.active.checked;if(!editing.name)return;const list=content.products;if(editingIndex<0)list.push(editing);else list[editingIndex]=editing;}else{for(const k of ['title','description','button','href'])editing[k]=f[k].value.trim();editing.active=f.active.checked;if(!editing.title||!editing.button)return;if(editingIndex<0)content.banners.push(editing);else content.banners[editingIndex]=editing;}changed();renderProducts();renderBanners();$('#editor').close();saveDraft(false);};
$('#close-editor').onclick=$('#cancel-editor').onclick=()=>$('#editor').close();
async function uploadImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw new Error('Escolha JPG, PNG ou WebP até 15 MB.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>80000000){bitmap.close();throw new Error('Imagem demasiado grande. Reduza a resolução.');}const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob;for(const q of [.85,.7,.55,.4]){blob=await new Promise(r=>canvas.toBlob(r,'image/webp',q));if(blob&&blob.size<=450000)break;}if(!blob||blob.type!=='image/webp'||blob.size>450000)throw new Error('Não foi possível optimizar a imagem. Escolha uma imagem mais pequena.');const bytes=new Uint8Array(await blob.arrayBuffer());const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');const path='assets/uploads/'+hash+'.webp';if(!assets.some(a=>a.path===path)){let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));assets.push({path,data:btoa(binary)});}return path;}
$('#hero-upload').onchange=async e=>{try{if(e.target.files[0]){content.hero.image=await uploadImage(e.target.files[0]);changed();renderBanners();}}catch(err){notice(err.message,true);}finally{e.target.value='';}};
for(const name of ['hero','pages']){$('#'+name+'-form').oninput=changed;$('#'+name+'-form').onsubmit=e=>{e.preventDefault();if(syncForms()){changed();saveDraft();}};}
$('#save-draft').onclick=()=>{if(syncForms())saveDraft();};
$('#restore-draft').onclick=()=>{try{const draft=JSON.parse(localStorage.getItem(draftKey));if(draft?.version!==1||!Array.isArray(draft.content?.products)||!Array.isArray(draft.assets))throw Error();content=draft.content;assets=draft.assets;const oldBase=draft.base;base=oldBase;render();changed();$('#saved-draft').hidden=true;notice('Rascunho restaurado. Reveja antes de publicar. Se o site tiver uma versão mais recente, a publicação será bloqueada para evitar sobrepor alterações.');}catch{notice('Não foi possível restaurar este rascunho.',true);}};
$('#discard-draft').onclick=()=>{localStorage.removeItem(draftKey);$('#saved-draft').hidden=true;};
$('#publish').onclick=()=>{if(!syncForms())return;$('#publish-summary').textContent=content.products.filter(p=>p.active).length+' produtos visíveis · '+content.banners.filter(b=>b.active).length+' destaques';$('#publish-dialog').showModal();};$('#cancel-publish').onclick=()=>$('#publish-dialog').close();
$('#confirm-publish').onclick=async()=>{if(busy)return;busy=true;$('#workspace').inert=true;$('.sidebar').inert=true;$('#confirm-publish').disabled=true;$('#publish-dialog').close();$('#publish').disabled=true;saveDraft(false);notice('A enviar as alterações para publicação…');try{const referenced=new Set([content.hero.image,...content.banners.map(b=>b.image),...content.products.flatMap(p=>[p.image,...p.images])]);const pending=assets.filter(a=>referenced.has(a.path));if(JSON.stringify({content,assets:pending}).length>3800000)throw new Error('Publique menos imagens de cada vez. O rascunho foi mantido.');const result=await api({action:'publish',base,content,assets:pending});base=result.head;dirty=false;localStorage.removeItem(draftKey);$('#saved-draft').hidden=true;$('#draft-state').textContent='Publicação em curso';notice(result.message);const expected=stable(content);let published=false;for(let i=0;i<24;i++){await new Promise(r=>setTimeout(r,5000));try{const response=await fetch('/content.json?check='+Date.now(),{cache:'no-store'});if(response.ok&&stable(await response.json())===expected){published=true;break;}}catch{}}if(published){assets=[];$('#draft-state').textContent='Publicado';notice('Publicado! A nova versão já está disponível na loja.');render();}else{notice('As alterações foram guardadas, mas a publicação ainda não foi confirmada. Consulte a loja dentro de instantes.');$('#draft-state').textContent='A aguardar publicação';}}catch(e){notice(e.message,true);$('#publish').disabled=false;if(e.status===401){$('#admin-view').hidden=true;$('#login-view').hidden=false;$('#login-message').textContent=e.message;}if(e.status===409){const button=document.createElement('button');button.textContent='Carregar versão actual';button.onclick=async()=>{try{await load();notice('Versão actual carregada. O rascunho antigo continua guardado neste navegador.');}catch(err){notice(err.message,true);}};$('#notice').append(button);}}finally{busy=false;$('#workspace').inert=false;$('.sidebar').inert=false;$('#confirm-publish').disabled=false;}};
window.addEventListener('beforeunload',e=>{if((dirty&&!draftSaved)||busy){e.preventDefault();e.returnValue='';}});
load().catch(e=>{$('#login-message').textContent=e.status===401?'':e.message;});
})();
